import{_ as t,o as s,c as i,ag as e}from"./chunks/framework.-Wrcbzkw.js";const u=JSON.parse('{"title":"PicKit - 在线图片工具箱","description":"","frontmatter":{},"headers":[],"relativePath":"project/PicKit.md","filePath":"project/PicKit.md","lastUpdated":1781418787000}'),n={name:"project/PicKit.md"};function l(p,a,r,d,h,o){return s(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="pickit-在线图片工具箱" tabindex="-1">PicKit - 在线图片工具箱 <a class="header-anchor" href="#pickit-在线图片工具箱" aria-label="Permalink to &quot;PicKit - 在线图片工具箱&quot;">​</a></h1><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p><a href="https://github.com/xxxeuniii/PicKit" target="_blank" rel="noreferrer">PicKit</a> 是一个简单高效的在线图片处理工具箱。项目基于 Vue 3 构建，图片处理过程全部在浏览器本地完成，无需上传到服务器，也无需注册登录。</p><p>PicKit 将常用的图片压缩、裁剪、格式转换和批量处理能力集中在一个网站中，适合日常开发、内容创作和办公场景使用。</p><p><strong>在线访问</strong>：<a href="https://pic-kit.vercel.app/" target="_blank" rel="noreferrer">https://pic-kit.vercel.app/</a></p><p><strong>核心流程</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选择本地图片</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>选择压缩、裁剪、转换或批量处理工具</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>浏览器本地完成图片处理</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>预览并下载处理结果</span></span></code></pre></div><hr><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>技术</th></tr></thead><tbody><tr><td>前端框架</td><td>Vue 3</td></tr><tr><td>构建工具</td><td>Vite</td></tr><tr><td>UI 组件库</td><td>Element Plus</td></tr><tr><td>路由</td><td>Vue Router</td></tr><tr><td>国际化</td><td>Vue I18n</td></tr><tr><td>图片处理</td><td>Canvas API</td></tr><tr><td>高质量缩放</td><td>Pica</td></tr><tr><td>图片裁剪</td><td>Cropper.js</td></tr><tr><td>PDF 生成</td><td>jsPDF</td></tr><tr><td>批量打包</td><td>JSZip</td></tr><tr><td>PWA</td><td>vite-plugin-pwa</td></tr><tr><td>部署</td><td>Vercel</td></tr></tbody></table><hr><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="图片压缩" tabindex="-1">图片压缩 <a class="header-anchor" href="#图片压缩" aria-label="Permalink to &quot;图片压缩&quot;">​</a></h3><p>通过调整图片质量和尺寸减小文件体积。图片在浏览器本地读取和处理，适合在上传网站、发送邮件或发布文章前快速压缩图片。</p><h3 id="图片裁剪" tabindex="-1">图片裁剪 <a class="header-anchor" href="#图片裁剪" aria-label="Permalink to &quot;图片裁剪&quot;">​</a></h3><p>基于 Cropper.js 提供可视化裁剪操作，支持自由裁剪和多种常用宽高比例。</p><h3 id="格式转换" tabindex="-1">格式转换 <a class="header-anchor" href="#格式转换" aria-label="Permalink to &quot;格式转换&quot;">​</a></h3><p>使用 Canvas API 在 PNG、JPEG 和 WebP 等常见图片格式之间进行转换，处理完成后可以直接下载目标格式文件。</p><h3 id="批量重命名" tabindex="-1">批量重命名 <a class="header-anchor" href="#批量重命名" aria-label="Permalink to &quot;批量重命名&quot;">​</a></h3><p>上传多张图片后按照统一规则批量重命名，并通过 JSZip 将结果打包下载，减少逐个修改文件名的重复操作。</p><h3 id="批量裁剪" tabindex="-1">批量裁剪 <a class="header-anchor" href="#批量裁剪" aria-label="Permalink to &quot;批量裁剪&quot;">​</a></h3><p>对多张图片应用统一裁剪规则，适合处理商品图、文章配图和社交媒体素材。</p><h3 id="图片转-pdf" tabindex="-1">图片转 PDF <a class="header-anchor" href="#图片转-pdf" aria-label="Permalink to &quot;图片转 PDF&quot;">​</a></h3><p>将多张图片按照顺序合并为一个 PDF 文件，方便整理扫描件、截图和图片资料。</p><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>PicKit 是一个纯前端应用，用户选择的图片不会上传到后端服务器。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本地图片文件</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├── File API：读取文件与图片信息</span></span>
<span class="line"><span>    ├── Canvas API：格式转换和图片导出</span></span>
<span class="line"><span>    ├── Pica：高质量图片缩放</span></span>
<span class="line"><span>    ├── Cropper.js：可视化裁剪</span></span>
<span class="line"><span>    ├── JSZip：批量文件打包</span></span>
<span class="line"><span>    └── jsPDF：生成 PDF 文件</span></span></code></pre></div><p>这种架构省去了后端存储和文件上传流程，既降低了部署复杂度，也避免了图片离开用户设备。</p><hr><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PicKit/</span></span>
<span class="line"><span>├── public/                 # 静态资源与 robots.txt</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── App.vue             # 应用根组件</span></span>
<span class="line"><span>│   ├── main.js             # 应用入口</span></span>
<span class="line"><span>│   ├── router/             # 页面路由</span></span>
<span class="line"><span>│   └── views/              # 图片工具页面</span></span>
<span class="line"><span>├── index.html              # HTML 入口与 Meta 信息</span></span>
<span class="line"><span>├── package.json            # 依赖与脚本</span></span>
<span class="line"><span>└── vite.config.js          # Vite 与 PWA 配置</span></span></code></pre></div><hr><h2 id="本地开发" tabindex="-1">本地开发 <a class="header-anchor" href="#本地开发" aria-label="Permalink to &quot;本地开发&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/xxxeuniii/PicKit.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PicKit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>常用命令：</p><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td>启动 Vite 开发服务器</td></tr><tr><td><code>npm run build</code></td><td>构建生产版本</td></tr><tr><td><code>npm run preview</code></td><td>本地预览生产构建</td></tr></tbody></table><hr><h2 id="国际化与-pwa" tabindex="-1">国际化与 PWA <a class="header-anchor" href="#国际化与-pwa" aria-label="Permalink to &quot;国际化与 PWA&quot;">​</a></h2><p>项目使用 Vue I18n 支持中文、英文和日文界面，使不同语言用户都可以直接使用。</p><p>通过 <code>vite-plugin-pwa</code> 提供 PWA 能力，用户可以将 PicKit 安装到桌面或移动设备，并获得更接近原生应用的访问体验。</p><hr><h2 id="seo-优化" tabindex="-1">SEO 优化 <a class="header-anchor" href="#seo-优化" aria-label="Permalink to &quot;SEO 优化&quot;">​</a></h2><p>为了提高工具网站的自然搜索收录，PicKit 已完成基础 SEO 配置：</p><ul><li>配置页面标题、描述、关键词和 robots Meta 标签</li><li>设置 canonical 链接</li><li>提供 <code>robots.txt</code></li><li>生成并提交 <code>sitemap.xml</code></li><li>为主要图片处理工具提供独立页面入口</li></ul><hr><h2 id="项目特点" tabindex="-1">项目特点 <a class="header-anchor" href="#项目特点" aria-label="Permalink to &quot;项目特点&quot;">​</a></h2><ol><li><strong>纯前端处理</strong>：无需后端服务，图片不会上传到服务器</li><li><strong>隐私友好</strong>：处理过程均在用户设备中完成</li><li><strong>功能集中</strong>：覆盖常见的单图和批量图片处理需求</li><li><strong>开箱即用</strong>：无需注册登录，打开网页即可使用</li><li><strong>多语言支持</strong>：支持中文、英文和日文</li><li><strong>可安装使用</strong>：通过 PWA 提供更便捷的访问方式</li></ol><hr><h2 id="当前限制与演进方向" tabindex="-1">当前限制与演进方向 <a class="header-anchor" href="#当前限制与演进方向" aria-label="Permalink to &quot;当前限制与演进方向&quot;">​</a></h2><ul><li>大尺寸图片和批量任务受浏览器内存与设备性能限制</li><li>可以使用 Web Worker 将复杂图片处理任务移出主线程</li><li>可以增加图片水印、旋转、滤镜和 EXIF 信息清理功能</li><li>可以进一步完善自动化测试和不同浏览器的兼容性验证</li><li>可以为批量任务增加进度管理、失败重试和处理参数预设</li></ul><hr><h2 id="项目链接" tabindex="-1">项目链接 <a class="header-anchor" href="#项目链接" aria-label="Permalink to &quot;项目链接&quot;">​</a></h2><ul><li>在线体验：<a href="https://pic-kit.vercel.app/" target="_blank" rel="noreferrer">https://pic-kit.vercel.app/</a></li><li>GitHub：<a href="https://github.com/xxxeuniii/PicKit" target="_blank" rel="noreferrer">xxxeuniii/PicKit</a></li><li>License：MIT</li></ul>`,54)])])}const b=t(n,[["render",l]]);export{u as __pageData,b as default};
